import gurobipy as gp
from gurobipy import GRB
customer_demand = {}
supply_capacity = {}
transportation_costs = {}
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src == 'customer_demand.csv':
        customer = vals['customer']
        demand = int(vals['demand'])
        customer_demand[customer] = demand
    elif src == 'supply_capacity.csv':
        store = vals['Unnamed: 0']
        capacity = int(vals['supply_capacity'])
        supply_capacity[store] = capacity
    elif src == 'transportation_costs.csv':
        store = vals['Unnamed: 0']
        transportation_costs[store] = {}
        for c in vals:
            if c != 'Unnamed: 0':
                transportation_costs[store][c] = float(vals[c])
stores = list(supply_capacity.keys())
customers = list(customer_demand.keys())
for s in stores:
    if s not in transportation_costs:
        raise ValueError(f'Missing transportation costs for store {s}')
    for c in customers:
        if c not in transportation_costs[s]:
            raise ValueError(f'Missing transportation cost for store {s}, customer {c}')
m = gp.Model('Walmart_Transportation')
x = m.addVars(stores, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((transportation_costs[s][c] * x[s, c] for s in stores for c in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[s, c] for s in stores)) == customer_demand[c] for c in customers), name='')
m.addConstrs((gp.quicksum((x[s, c] for c in customers)) <= supply_capacity[s] for s in stores), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')